/**
 * The media catalogue, in two parts (both generated by tools/media, `npm run media:process`):
 * - media.gen.ts, in the entry bundle: what the first screens need synchronously — the public home's hero, herohd
 *   and presence clips, her usual home loop (hero, herohd, breath), her costume / prop stills, the loading screen's clip;
 * - media.scene.gen.ts, a lazy chunk: everything else (tools/media SCENE_MEDIA_ID) — the scenes' clips (her scene
 *   shots, seated talk / idle loops, the system scenes, her confession), every variant clip (entrance, close-up, home
 *   loop) and her morning clips (her morning room, her morning hero loop). It loads when her room opens — at once when
 *   her room may show a morning or variant look, in idle time otherwise — or when a screen that needs it asks.
 *
 * `mediaEntry` answers from the core catalogue, and from the lazy one once it is loaded; a screen that needs one of
 * its clips (the scene player, the wake-up screen, her room in the morning or in a variant look) awaits
 * `loadSceneMedia()` (or components/stage.tsx `useSceneMedia()`) before it resolves one.
 */
import { MEDIA, type MediaEntry } from './media.gen';
import { ALICE_ENTRANCE_MEDIA } from './aliceEntranceMedia';
import { ALICE_FEEDBACK_MEDIA } from './aliceFeedbackMedia';
import { EIMI_FEEDBACK_MEDIA } from './eimiFeedbackMedia';
import { EIMI_BONUS_MEDIA } from './eimiBonusMedia';
import { MAHIRO_FEEDBACK_MEDIA } from './mahiroFeedbackMedia';
import { NANA_FEEDBACK_MEDIA } from './nanaFeedbackMedia';
import { UNPAI_FEEDBACK_MEDIA } from './unpaiFeedbackMedia';
// The scene catalogue's address in the build (a hashed asset, fetched on demand; N-61).
import SCENE_URL from './media.scene.gen.json?url';

let scene: Record<string, MediaEntry> | null = null;
let loading: Promise<boolean> | null = null;

/** A clip by its exact id: approved owner replacements first, then the generated catalogues. */
export const mediaEntry = (id: string): MediaEntry | undefined => {
  const nanaId = /^nana-(?:enter|idle|react-[a-j])-9x16$/.test(id) ? id.replace('-9x16', '-16x9') : id;
  const unpaiId = /^unpai-(?:enter|idle|react-[a-j])-9x16$/.test(id) ? id.replace('-9x16', '-16x9') : id;
  const mahiroId = /^mahiro-(?:enter|idle|react-[a-j])-9x16$/.test(id) ? id.replace('-9x16', '-16x9') : id;
  const approved = EIMI_BONUS_MEDIA[id] ?? ALICE_ENTRANCE_MEDIA[id] ?? ALICE_FEEDBACK_MEDIA[id] ?? EIMI_FEEDBACK_MEDIA[id]
    ?? MAHIRO_FEEDBACK_MEDIA[mahiroId] ?? NANA_FEEDBACK_MEDIA[nanaId] ?? UNPAI_FEEDBACK_MEDIA[unpaiId];
  if (approved) return approved;
  // Eimi uses only the approved idle and feedback set. Any other moving slot resolves to her current idle master.
  if (id.startsWith('eimi-')) return id === 'eimi-costume' || id === 'eimi-prop' ? undefined : EIMI_FEEDBACK_MEDIA['eimi-idle-16x9'];
  return MEDIA[id] ?? scene?.[id];
};

/** Whether the scene catalogue is here (every `mediaEntry` answer is then final). */
export const sceneMediaLoaded = (): boolean => scene !== null;

/**
 * Loads the scene catalogue once; resolves true when it is here. A failed load (offline, a stale deploy) resolves
 * false and the next call tries again — the screens then play what the core catalogue has, as they do for a clip
 * this build lacks.
 */
export function loadSceneMedia(): Promise<boolean> {
  loading ??= (async () => {
    // N-48: a failed chunk load (a flaky network, a deploy mid-visit) is tried again with a short backoff before the
    // screens hear it failed; the next call starts over.
    for (let attempt = 0; attempt < SCENE_MEDIA_TRIES; attempt++) {
      if (attempt) await new Promise((r) => setTimeout(r, SCENE_MEDIA_BACKOFF_MS * 3 ** (attempt - 1)));
      try {
        scene = await loadScene(attempt);
        return true;
      } catch { /* try again */ }
    }
    loading = null;
    return false;
  })();
  return loading;
}

/** Tries per load and the first wait between them (then ×3). */
export const SCENE_MEDIA_TRIES = 3;
export const SCENE_MEDIA_BACKOFF_MS = 400;
type SceneCatalogue = Record<string, MediaEntry>;
/**
 * N-61: the scene catalogue is a JSON asset (media.scene.gen.json, a hashed file in the build), fetched — not a module
 * imported: a browser keeps a failed module import failed (the retry never reaches the network), a fetch is really
 * tried again. Each retry asks under a fresh query string, so no cache stands between it and the server.
 */
const fetchScene = async (attempt: number): Promise<SceneCatalogue> => {
  const res = await fetch(attempt ? `${SCENE_URL}${SCENE_URL.includes('?') ? '&' : '?'}r=${Date.now().toString(36)}-${attempt}` : SCENE_URL, { cache: attempt ? 'no-store' : 'default' });
  if (!res.ok) throw new Error(`scene_catalogue_${res.status}`);
  return (await res.json()) as SceneCatalogue;
};
/** The catalogue's loader (tests replace it: a failing network). */
let loadScene: (attempt: number) => Promise<SceneCatalogue> = fetchScene;
export const setSceneLoader = (fn: (attempt: number) => Promise<SceneCatalogue>) => { loadScene = fn; scene = null; loading = null; };
export const resetSceneLoader = () => setSceneLoader(fetchScene);

/** Loads the scene catalogue when the browser is idle (her room: a scene may start from here). Returns a cancel. */
export function preloadSceneMedia(): () => void {
  if (scene || typeof window === 'undefined') return () => undefined;
  const w = window as unknown as { requestIdleCallback?: (cb: () => void) => number; cancelIdleCallback?: (h: number) => void };
  if (w.requestIdleCallback) {
    const h = w.requestIdleCallback(() => void loadSceneMedia());
    return () => w.cancelIdleCallback?.(h);
  }
  const t = setTimeout(() => void loadSceneMedia(), 1200);
  return () => clearTimeout(t);
}
